css:
body :where([data-bz-node="rt"]) .bz-block{padding:0}
body :where([data-bz-node="rt"]) .bz-container{padding:0;max-width:none}
body [data-bz-node="rt"]>.bz-container{padding-inline:0}

body [data-bz-node="rt"]{background:#2b2824;padding:82px 0 82px;color:#fff;text-align:center}
body [data-bz-node="rt"]>.bz-container{max-width:var(--container)}
body [data-bz-node="rt-h"] h2{font:700 38px/41px var(--font-heading);letter-spacing:0;text-transform:uppercase;color:#fff;margin:0 auto;max-width:380px}
body [data-bz-node="rt-text"] .bz-text{max-width:290px;margin:23px auto 0}
body [data-bz-node="rt-text"] p{font:400 13px/23.5px var(--font-body);color:#fff;margin:0}
body [data-bz-node="rt-cta"]{margin-top:26px}
body [data-bz-node="rt-cta"] .bz-btns{margin:0;justify-content:center}
body [data-bz-node="rt-cta"] .bz-btn{display:inline-flex;align-items:center;justify-content:center;height:50px;padding:0 20px;border:0;border-radius:2px;background:var(--accent);color:#fff;font:700 11px/1 var(--font-body);letter-spacing:.18em;text-transform:uppercase;text-decoration:none;padding:0 27px;height:50px}
body [data-bz-node="rt-cta"] .bz-btn:hover{background:var(--accent-dark)}
body [data-bz-node="rt-call"]{margin-top:24px}
body [data-bz-node="rt-call"] .bz-text{max-width:none}
body [data-bz-node="rt-call"] p{display:inline-flex;align-items:center;gap:9px;font:400 12px/1 var(--font-body);color:#fff;margin:0;letter-spacing:.02em}
body [data-bz-node="rt-call"] p::before{content:"";width:17px;height:17px;background:#fff;-webkit-mask:url(/icons/phone.svg) center/16px no-repeat;mask:url(/icons/phone.svg) center/16px no-repeat}
body [data-bz-node="rt-call"] a{color:#fff;margin-left:6px}
body [data-bz-node="rt-call"] a:hover{color:var(--accent)}
@media (max-width:640px){
  body [data-bz-node="rt"]{padding:56px 20px}
  body [data-bz-node="rt-h"] h2{font-size:30px;line-height:32px}
}
